INSERT INTO changelog (title, body, created_at) VALUES ('Креативи: промпти з памʼяттю результатів, патерни і журнал змін реклами', 'Клієнт → Meta → «Креативи» → «Промпти креативів»: обираєш формат (квадрат, сторіс, карусель, сценарій відео), за бажанням кут і побажання → Джері пише готове ТЗ для Claude / Claude Code з даних реклами: що вже дає дешеві ліди, патерни з розбору, бренд клієнта і результати минулих промптів. Копіюєш → робиш креатив → запускаєш. Потім у промпті відмічаєш, які оголошення з нього зроблені — і бачиш його ліди, ціну ліда і CTR. Ставиш «спрацював / не спрацював» — Джері враховує це в наступних промптах. «Бренд клієнта» — кольори, шрифти, тон: заповни один раз.
«Висновки»: розбір Джері тепер шукає патерни (що спільного в креативах з дешевими лідами). Нижче «Журнал змін реклами»: що змінили, чому, чого чекаємо — і через кілька днів що вийшло. Джері записує зміни сам, коли ти про них кажеш, і враховує журнал у розборі.
Тумблер — «Можливості» → «Креативи і журнал змін реклами».', datetime('now'));
